class Solution {
public:
    double equalizeWater(vector<int>& buckets, int loss) {
        double low = 0.0, high = 0.0;
        for (int b : buckets) high = max(high, (double)b);
        double factor = (100 - loss) / 100.0;
        for (int iter = 0; iter < 80; iter++) {
            double mid = (low + high) / 2.0;
            double excess = 0.0, deficit = 0.0;
            for (int b : buckets) {
                if (b > mid) excess += (b - mid) * factor;
                else deficit += (mid - b);
            }
            if (excess >= deficit) low = mid;
            else high = mid;
        }
        return low;
    }
};

