var equalizeWater = function(buckets, loss) {
    let low = 0.0, high = Math.max(...buckets);
    const factor = (100 - loss) / 100.0;
    for (let iter = 0; iter < 80; iter++) {
        const mid = (low + high) / 2.0;
        let excess = 0.0, deficit = 0.0;
        for (const b of buckets) {
            if (b > mid) excess += (b - mid) * factor;
            else deficit += (mid - b);
        }
        if (excess >= deficit) low = mid;
        else high = mid;
    }
    return low;
};
